1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// Before 是修改前的完整期望配置。
42		Before json.RawMessage
43		// After 是修改后的完整期望配置。
44		After json.RawMessage
45	}
46	
47	// deviceState 是单台设备的内部状态。
48	type deviceState struct {
49		Version        string
50		Online         bool
51		Revision       uint64
52		Desired        json.RawMessage
53		Reported       json.RawMessage
54		LastSeq        uint64
55		LastReportTime time.Time
56		// DiffSince 记录每条差异路径首次出现的时间。
57		DiffSince map[string]time.Time
58		Audit     []AuditRecord
59	}
60	
61	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
62	func (d *deviceState) refreshDiff(t time.Time) {
63		entries := computeDiff(d.Desired, d.Reported)
64		next := make(map[string]time.Time, len(entries))
65		for _, e := range entries {
66			if since, ok := d.DiffSince[e.Path]; ok {
67				next[e.Path] = since
68			} else {
69				next[e.Path] = t
70			}
71		}
72		d.DiffSince = next
73	}
74	
75	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
76	// Store 可安全并发使用。
77	type Store struct {
78		mu      sync.Mutex
79		dir     string
80		closed  bool
81		devices map[string]*deviceState
82	}
83	
84	// Open 打开（必要时创建）位于 dir 的本地影子存储。
85	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
86	func Open(dir string) (*Store, error) {
87		if err := os.MkdirAll(dir, 0o755); err != nil {
88			return nil, fmt.Errorf("shadow: create store dir: %w", err)
89		}
90		s := &Store{dir: dir, devices: map[string]*deviceState{}}
91		data, err := os.ReadFile(s.filePath())
92		if errors.Is(err, fs.ErrNotExist) {
93			return s, nil
94		}
95		if err != nil {
96			return nil, fmt.Errorf("shadow: read store: %w", err)
97		}
98		if err := s.restore(data); err != nil {
99			return nil, err
100		}
101		return s, nil
102	}
103	
104	// Close 关闭存储。关闭后的操作返回 ErrClosed。
105	func (s *Store) Close() error {
106		s.mu.Lock()
107		defer s.mu.Unlock()
108		if s.closed {
109			return ErrClosed
110		}
111		s.closed = true
112		return nil
113	}
114	
115	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
116	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
117	func (s *Store) Register(deviceID, version string) error {
118		s.mu.Lock()
119		defer s.mu.Unlock()
120		if err := s.checkOpen(); err != nil {
121			return err
122		}
123		if deviceID == "" {
124			return ErrInvalidDeviceID
125		}
126		if version == "" {
127			return ErrInvalidVersion
128		}
129		if _, ok := s.devices[deviceID]; ok {
130			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
131		}
132		return s.commit(func() error {
133			s.devices[deviceID] = &deviceState{
134				Version:   version,
135				Desired:   json.RawMessage(`{}`),
136				Reported:  json.RawMessage(`{}`),
137				DiffSince: map[string]time.Time{},
138			}
139			return nil
140		})
141	}
142	
143	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
144	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
145	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
146	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
147		s.mu.Lock()
148		defer s.mu.Unlock()
149		if err := s.checkOpen(); err != nil {
150			return 0, err
151		}
152		d, err := s.lookup(deviceID)
153		if err != nil {
154			return 0, err
155		}
156		if operator == "" {
157			return 0, ErrInvalidOperator
158		}
159		if at.IsZero() {
160			return 0, ErrInvalidTime
161		}
162		cfg, err := validateConfig(config)
163		if err != nil {
164			return 0, err
165		}
166		if revision != d.Revision {
167			return 0, fmt.Errorf("%w: want %d, got %d", ErrRevisionConflict, d.Revision, revision)
168		}
169		var newRevision uint64
170		err = s.commit(func() error {
171			before := d.Desired
172			d.Desired = cfg
173			d.Revision++
174			newRevision = d.Revision
175			d.Audit = append(d.Audit, AuditRecord{
176				DeviceID: deviceID,
177				Operator: operator,
178				Time:     at,
179				Revision: newRevision,
180				Before:   cloneRaw(before),
181				After:    cloneRaw(cfg),
182			})
183			d.refreshDiff(at)
184			return nil
185		})
186		if err != nil {
187			return 0, err
188		}
189		return newRevision, nil
190	}
191	
192	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
193	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
194	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
195	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
196		s.mu.Lock()
197		defer s.mu.Unlock()
198		if err := s.checkOpen(); err != nil {
199			return err
200		}
201		d, err := s.lookup(deviceID)
202		if err != nil {
203			return err
204		}
205		if seq == 0 {
206			return ErrInvalidSequence
207		}
208		if at.IsZero() {
209			return ErrInvalidTime
210		}
211		if version == "" {
212			return ErrInvalidVersion
213		}
214		cfg, err := validateConfig(config)
215		if err != nil {
216			return err
217		}
218		switch {
219		case seq < d.LastSeq:
220			return fmt.Errorf("%w: last accepted %d, got %d", ErrStaleSequence, d.LastSeq, seq)
221		case seq == d.LastSeq:
222			if version == d.Version && at.Equal(d.LastReportTime) && rawEqual(cfg, d.Reported) {
223				return nil // 重复上报：成功返回，不改变状态
224			}
225			return fmt.Errorf("%w: sequence %d", ErrReportConflict, seq)
226		}
227		return s.commit(func() error {
228			d.Reported = cfg
229			d.Version = version
230			d.Online = true
231			d.LastSeq = seq
232			d.LastReportTime = at
233			d.refreshDiff(at)
234			return nil
235		})
236	}
237	
238	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
239	func (s *Store) SetOffline(deviceID string) error {
240		s.mu.Lock()
241		defer s.mu.Unlock()
242		if err := s.checkOpen(); err != nil {
243			return err
244		}
245		d, err := s.lookup(deviceID)
246		if err != nil {
247			return err
248		}
249		return s.commit(func() error {
250			d.Online = false
251			return nil
252		})
253	}
254	
255	// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
256	// 调用方修改不影响已保存的记录。
257	func (s *Store) Get(deviceID string) (View, error) {
258		s.mu.Lock()
259		defer s.mu.Unlock()
260		if err := s.checkOpen(); err != nil {
261			return View{}, err
262		}
263		d, err := s.lookup(deviceID)
264		if err != nil {
265			return View{}, err
266		}
267		return View{
268			DeviceID: deviceID,
269			Version:  d.Version,
270			Online:   d.Online,
271			Revision: d.Revision,
272			Desired:  cloneRaw(d.Desired),
273			Reported: cloneRaw(d.Reported),
274			LastSeq:  d.LastSeq,
275		}, nil
276	}
277	
278	// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
279	func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
280		s.mu.Lock()
281		defer s.mu.Unlock()
282		if err := s.checkOpen(); err != nil {
283			return nil, err
284		}
285		d, err := s.lookup(deviceID)
286		if err != nil {
287			return nil, err
288		}
289		entries := computeDiff(d.Desired, d.Reported)
290		for i := range entries {
291			entries[i].Since = d.DiffSince[entries[i].Path]
292		}
293		return entries, nil
294	}
295	
296	// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
297	func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
298		s.mu.Lock()
299		defer s.mu.Unlock()
300		if err := s.checkOpen(); err != nil {
301			return nil, err
302		}
303		d, err := s.lookup(deviceID)
304		if err != nil {
305			return nil, err
306		}
307		out := make([]AuditRecord, len(d.Audit))
308		for i, rec := range d.Audit {
309			out[i] = rec
310			out[i].Before = cloneRaw(rec.Before)
311			out[i].After = cloneRaw(rec.After)
312		}
313		return out, nil
314	}
315	
316	func (s *Store) checkOpen() error {
317		if s.closed {
318			return ErrClosed
319		}
320		return nil
321	}
322	
323	func (s *Store) lookup(deviceID string) (*deviceState, error) {
324		if deviceID == "" {
325			return nil, ErrInvalidDeviceID
326		}
327		d, ok := s.devices[deviceID]
328		if !ok {
329			return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
330		}
331		return d, nil
332	}
333	
334	// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
335	// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
336	// 调用时必须持有 s.mu。
337	func (s *Store) commit(mutate func() error) error {
338		snapshot, err := s.marshal()
339		if err != nil {
340			return err
341		}
342		if err := mutate(); err != nil {
343			return err
344		}
345		if err := s.persist(); err != nil {
346			// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
347			_ = s.restore(snapshot)
348			return err
349		}
350		return nil
351	}
352	
353	func (s *Store) filePath() string {
354		return filepath.Join(s.dir, storeFileName)
355	}
356	
357	// persist 把当前状态原子写入存储文件。
358	func (s *Store) persist() error {
359		data, err := s.marshal()
360		if err != nil {
361			return err
362		}
363		tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
364		if err != nil {
365			return fmt.Errorf("shadow: save store: %w", err)
366		}
367		tmpName := tmp.Name()
368		if _, err := tmp.Write(data); err != nil {
369			tmp.Close()
370			os.Remove(tmpName)
371			return fmt.Errorf("shadow: save store: %w", err)
372		}
373		if err := tmp.Sync(); err != nil {
374			tmp.Close()
375			os.Remove(tmpName)
376			return fmt.Errorf("shadow: save store: %w", err)
377		}
378		if err := tmp.Close(); err != nil {
379			os.Remove(tmpName)
380			return fmt.Errorf("shadow: save store: %w", err)
381		}
382		if err := os.Rename(tmpName, s.filePath()); err != nil {
383			os.Remove(tmpName)
384			return fmt.Errorf("shadow: save store: %w", err)
385		}
386		return nil
387	}
388	
389	// diskStore 是存储文件的磁盘格式。
390	type diskStore struct {
391		Format  int                  `json:"format"`
392		Devices map[string]diskState `json:"devices"`
393	}
394	
395	type diskState struct {
396		Version        string               `json:"version"`
397		Online         bool                 `json:"online"`
398		Revision       uint64               `json:"revision"`
399		Desired        json.RawMessage      `json:"desired"`
400		Reported       json.RawMessage      `json:"reported"`
401		LastSeq        uint64               `json:"lastSeq"`
402		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
403		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
404		Audit          []diskAudit          `json:"audit,omitempty"`
405	}
406	
407	type diskAudit struct {
408		Operator string          `json:"operator"`
409		Time     time.Time       `json:"time"`
410		Revision uint64          `json:"revision"`
411		Before   json.RawMessage `json:"before"`
412		After    json.RawMessage `json:"after"`
413	}
414	
415	func (s *Store) marshal() ([]byte, error) {
416		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
417		for id, d := range s.devices {
418			ds := diskState{
419				Version:        d.Version,
420				Online:         d.Online,
421				Revision:       d.Revision,
422				Desired:        cloneRaw(d.Desired),
423				Reported:       cloneRaw(d.Reported),
424				LastSeq:        d.LastSeq,
425				LastReportTime: d.LastReportTime,
426				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
427			}
428			for p, t := range d.DiffSince {
429				ds.DiffSince[p] = t
430			}
431			for _, rec := range d.Audit {
432				ds.Audit = append(ds.Audit, diskAudit{
433					Operator: rec.Operator,
434					Time:     rec.Time,
435					Revision: rec.Revision,
436					Before:   cloneRaw(rec.Before),
437					After:    cloneRaw(rec.After),
438				})
439			}
440			disk.Devices[id] = ds
441		}
442		data, err := json.Marshal(disk)
443		if err != nil {
444			return nil, fmt.Errorf("shadow: encode store: %w", err)
445		}
446		return data, nil
447	}
448	
449	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
450	// ErrCorruptStorage，绝不按空数据覆盖。
451	func (s *Store) restore(data []byte) error {
452		var disk diskStore
453		if err := json.Unmarshal(data, &disk); err != nil {
454			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
455		}
456		if disk.Format != storeFormat {
457			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
458		}
459		devices := make(map[string]*deviceState, len(disk.Devices))
460		for id, ds := range disk.Devices {
461			if id == "" {
462				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
463			}
464			if _, ok := decodeObject(ds.Desired); !ok {
465				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
466			}
467			if _, ok := decodeObject(ds.Reported); !ok {
468				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
469			}
470			d := &deviceState{
471				Version:        ds.Version,
472				Online:         ds.Online,
473				Revision:       ds.Revision,
474				Desired:        cloneRaw(ds.Desired),
475				Reported:       cloneRaw(ds.Reported),
476				LastSeq:        ds.LastSeq,
477				LastReportTime: ds.LastReportTime,
478				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
479			}
480			for p, t := range ds.DiffSince {
481				d.DiffSince[p] = t
482			}
483			var lastRev uint64
484			for _, da := range ds.Audit {
485				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 || da.Revision <= lastRev {
486					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
487				}
488				if _, ok := decodeObject(da.Before); !ok {
489					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
490				}
491				if _, ok := decodeObject(da.After); !ok {
492					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
493				}
494				lastRev = da.Revision
495				d.Audit = append(d.Audit, AuditRecord{
496					DeviceID: id,
497					Operator: da.Operator,
498					Time:     da.Time,
499					Revision: da.Revision,
500					Before:   cloneRaw(da.Before),
501					After:    cloneRaw(da.After),
502				})
503			}
504			devices[id] = d
505		}
506		s.devices = devices
507		return nil
508	}
509

