func TestUpgradeSaveFailureRollsBack(t *testing.T) {
	s, dir := openTemp(t)
	if err := s.RegisterUpgrade("2.0", []string{"1.0"}); err != nil {
		t.Fatal(err)
	}
	mustRegister(t, s, "dev-1", "1.0")
