	if err := s.Advance("a1", upWinEnd); err != nil {
		t.Fatal(err)
	}
	info, _ = s.GetDeviceUpgrade("dev-1")
	if info.Status != DevicePending {
		t.Fatalf("at window end should not dispatch: %+v", info)
